// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;

    function setUp() public { c = new EtherCartel(); }

    function testFuzz_property(uint256 waitSeconds, address actor, address ref) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(ref != address(0));
        c.seedMarket(1000);
        vm.prank(actor);
        c.getFreeKilo();
        uint256 before = c.Kilos(actor);
        // ensure at least one full production period has elapsed so newKilo >= 1
        uint256 elapsed = bound(waitSeconds, c.DRUGS_TO_PRODUCE_1KILO(), type(uint48).max);
        vm.warp(block.timestamp + elapsed);
        vm.prank(actor);
        c.collectDrugs(ref);
        uint256 afterKilos = c.Kilos(actor);
        // General rule: collecting drugs only accumulates kilos; the balance never falls below what the user held.
        assertTrue(afterKilos >= before, "collectDrugs decreased kilos");
    }
}
